// Remote button -> intent. Deliberately free of view names: the shell owns
// the view list (views.js) and resolves these against it, so this node never
// needs editing when a view is added.
//
//   next / prev  - step the arrow rotation, relative to what's ON SCREEN
//   blank        - show the shell's OFF_VIEW
//   resume       - clear the retained override, schedule takes back over
//
// 'on' publishes the retained clear directly instead of sending an intent, so
// it still works when the panel is offline (the shell isn't there to relay it).

const MAP = {
    arrow_right_click: { topic: "wallpanel/command",  payload: "next"  },
    arrow_left_click:  { topic: "wallpanel/command",  payload: "prev"  },
    off:               { topic: "wallpanel/command",  payload: "blank" },
    on:                { topic: "wallpanel/override", payload: "", retain: true },
};

const action = (msg.payload && msg.payload.action) || "";
if (!action) { return null; }               // ignore non-action messages

const out = MAP[action];
if (!out) { return null; }                  // any other button: ignore

return out;
